/* From Uiverse.io by revanth-004  - Tags: sun, app, css, mountains, scenery, art */
.__UIV_SCOPE__ .center {
  display: flex;
  justify-content: center;
  align-items: center;
}
.__UIV_SCOPE__ .design {
  height: 200px;
  width: 200px;
  border-radius: 40px;
  background: rgb(255, 11, 0);
  background: linear-gradient(
    180deg,
    rgba(255, 11, 0, 1) 13%,
    rgba(255, 158, 0, 1) 100%
  );
  position: relative;
  overflow: hidden;
}

.__UIV_SCOPE__ .color-border {
  border-radius: 50%;
  background-color: #ffffff20;
  box-shadow: 0px 0px 10px 2px rgba(0, 0, 0, 0.1);
}
.__UIV_SCOPE__ .circle-1 {
  height: 220px;
  width: 220px;
  position: absolute;
  right: -50px;
  top: -50px;
}
.__UIV_SCOPE__ .circle-2 {
  height: 180px;
  width: 180px;
}
.__UIV_SCOPE__ .circle-3 {
  height: 140px;
  width: 140px;
}
.__UIV_SCOPE__ .circle-4 {
  height: 105px;
  width: 105px;
}
.__UIV_SCOPE__ .circle-5 {
  height: 70px;
  width: 70px;
  border-radius: 50%;
  background-color: #ffffff;
}

.__UIV_SCOPE__ .shape {
  height: 200px;
  width: 200px;
  background-color: #484848;
  transform: rotate(45deg);
  position: absolute;
}
.__UIV_SCOPE__ .shadow {
  box-shadow: 0px 0px 20px 0px rgba(0, 0, 0, 0.75);
}
.__UIV_SCOPE__ .mountain-1 {
  z-index: 1;
  bottom: -100px;
  left: -100px;
}
.__UIV_SCOPE__ .mountain-2 {
  bottom: -110px;
  left: -30px;
}
.__UIV_SCOPE__ .mountain-3 {
  z-index: 2;
  bottom: -150px;
  left: 90px;
}
